/* @autogenerated */
package net.civeira.phylax.features.oauth.consent.infrastructure.driven;

import java.time.OffsetDateTime;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.trustedclient.domain.TrustedClient;
import net.civeira.phylax.features.access.trustedclient.domain.TrustedClientReference;
import net.civeira.phylax.features.access.trustedclient.domain.gateway.TrustedClientFilter;
import net.civeira.phylax.features.access.trustedclient.domain.gateway.TrustedClientReadRepositoryGateway;
import net.civeira.phylax.features.access.user.domain.User;
import net.civeira.phylax.features.access.user.domain.gateway.UserFilter;
import net.civeira.phylax.features.access.user.domain.gateway.UserReadRepositoryGateway;
import net.civeira.phylax.features.access.userconsentedscopes.domain.UserConsentedScopes;
import net.civeira.phylax.features.access.userconsentedscopes.domain.UserConsentedScopesChangeSet;
import net.civeira.phylax.features.access.userconsentedscopes.domain.gateway.UserConsentedScopesFilter;
import net.civeira.phylax.features.access.userconsentedscopes.domain.gateway.UserConsentedScopesReadRepositoryGateway;
import net.civeira.phylax.features.access.userconsentedscopes.domain.gateway.UserConsentedScopesWriteRepositoryGateway;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationChallenge;
import net.civeira.phylax.features.oauth.consent.domain.ClientConsentSummary;
import net.civeira.phylax.features.oauth.consent.domain.ScopePermission;
import net.civeira.phylax.features.oauth.consent.domain.gateway.ScopeApprovalGateway;
import net.civeira.phylax.features.oauth.consent.domain.gateway.ScopesConsentGateway;

/**
 * ACL adapter that bridges the OIDC scope consent protocol port to the Access bounded context.
 *
 * Resolves username → User UID and clientId → TrustedClient UID before operating on
 * UserConsentedScopes records. Also implements ScopeApprovalGateway so a single bean handles both
 * the persistence port and the OIDC step port.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ScopesConsentAdapter implements ScopesConsentGateway, ScopeApprovalGateway {

  private final UserReadRepositoryGateway users;
  private final TrustedClientReadRepositoryGateway clients;
  private final UserConsentedScopesReadRepositoryGateway consentRead;
  private final UserConsentedScopesWriteRepositoryGateway consentWrite;

  // -------------------------------------------------------------------------
  // ScopesConsentGateway
  // -------------------------------------------------------------------------

  @Override
  public List<ScopePermission> pendingScopes(String tenant, String username, String clientId,
      List<String> scopes) {
    if (scopes.isEmpty()) {
      return List.of();
    }
    User user = users.find(UserFilter.builder().name(username).build()).orElse(null);
    if (user == null) {
      return toPermissions(scopes);
    }
    TrustedClient client =
        clients.find(TrustedClientFilter.builder().code(clientId).build()).orElse(null);
    if (client == null) {
      return toPermissions(scopes);
    }
    Set<String> granted = loadGrantedScopes(user, client);
    return scopes.stream().filter(s -> !granted.contains(s)).map(this::toPermission).toList();
  }

  @Override
  public void storeAcceptedScopes(String tenant, String username, String clientId,
      List<String> scopes) {
    if (scopes.isEmpty()) {
      return;
    }
    User user = users.find(UserFilter.builder().name(username).build()).orElse(null);
    if (user == null) {
      return;
    }
    TrustedClient client =
        clients.find(TrustedClientFilter.builder().code(clientId).build()).orElse(null);
    if (client == null) {
      return;
    }
    persistScopes(user, client, scopes);
  }

  @Override
  public List<ClientConsentSummary> listGrantedByUser(String tenant, String username) {
    User user = users.find(UserFilter.builder().name(username).build()).orElse(null);
    if (user == null) {
      return List.of();
    }
    List<UserConsentedScopes> consents =
        consentRead.list(UserConsentedScopesFilter.builder().user(user).build()).stream()
            .filter(c -> Boolean.TRUE.equals(c.isGranted())).toList();

    Map<String, List<UserConsentedScopes>> byClient =
        consents.stream().collect(Collectors.groupingBy(UserConsentedScopes::getTrustedClientUid));

    return byClient.entrySet().stream().map(entry -> {
      String clientUid = entry.getKey();
      List<UserConsentedScopes> clientConsents = entry.getValue();
      TrustedClient client =
          clients.find(TrustedClientFilter.builder().uid(clientUid).build()).orElse(null);
      List<String> scopes = clientConsents.stream().map(c -> c.getScope().orElse(null))
          .filter(s -> s != null).sorted().toList();
      OffsetDateTime lastAt = clientConsents.stream().map(c -> c.getDecisionAt().orElse(null))
          .filter(d -> d != null).max(OffsetDateTime::compareTo).orElse(null);
      return new ClientConsentSummary(clientUid, client != null ? client.getCode() : clientUid,
          client != null ? client.getClientName() : Optional.empty(), scopes,
          Optional.ofNullable(lastAt));
    }).toList();
  }

  @Override
  public void revokeClientConsent(String tenant, String username, String clientUid) {
    User user = users.find(UserFilter.builder().name(username).build()).orElse(null);
    if (user == null) {
      return;
    }
    List<UserConsentedScopes> consents = consentWrite.listForUpdate(UserConsentedScopesFilter
        .builder().user(user).trustedClient(TrustedClientReference.of(clientUid)).build());
    for (UserConsentedScopes consent : consents) {
      consentWrite.delete(consent.delete());
    }
  }

  @Override
  public void revokeScopeConsent(String tenant, String username, String clientUid, String scope) {
    User user = users.find(UserFilter.builder().name(username).build()).orElse(null);
    if (user == null) {
      return;
    }
    consentWrite
        .listForUpdate(UserConsentedScopesFilter.builder().user(user)
            .trustedClient(TrustedClientReference.of(clientUid)).build())
        .stream().filter(c -> scope.equals(c.getScope().orElse(null)))
        .forEach(c -> consentWrite.delete(c.delete()));
  }

  // -------------------------------------------------------------------------
  // ScopeApprovalGateway — delegates to the consent logic above
  // -------------------------------------------------------------------------

  @Override
  public List<ScopePermission> pendingApprovals(String tenant, String username, String clientId,
      List<String> requestedScopes, List<AuthenticationChallenge> completedChallenges) {
    return pendingScopes(tenant, username, clientId, requestedScopes);
  }

  @Override
  public void storeApprovedScopes(String tenant, String username, String clientId,
      List<String> acceptedScopes) {
    storeAcceptedScopes(tenant, username, clientId, acceptedScopes);
  }

  // -------------------------------------------------------------------------
  // Helpers
  // -------------------------------------------------------------------------

  private Set<String> loadGrantedScopes(User user, TrustedClient client) {
    return consentRead
        .list(UserConsentedScopesFilter.builder().user(user).trustedClient(client).build()).stream()
        .filter(c -> Boolean.TRUE.equals(c.isGranted())).map(c -> c.getScope().orElse(null))
        .filter(s -> s != null).collect(Collectors.toSet());
  }

  private void persistScopes(User user, TrustedClient client, List<String> scopes) {
    Set<String> existing = loadGrantedScopes(user, client);
    for (String scope : scopes) {
      if (!existing.contains(scope)) {
        UserConsentedScopes consent =
            UserConsentedScopes.create(new UserConsentedScopesChangeSet().newUid().user(user)
                .trustedClient(client).scope(scope).granted(true).decisionAt(OffsetDateTime.now()));
        consentWrite.create(consent);
      }
    }
  }

  private List<ScopePermission> toPermissions(List<String> scopes) {
    return scopes.stream().map(this::toPermission).toList();
  }

  private ScopePermission toPermission(String scope) {
    return ScopePermission.builder().scope(scope).required(false).label(scope).description(scope)
        .build();
  }
}
